import itertools

def f(q, p):
    a, b, c = q
    x, y, z = p
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

def solve():
    # All possible triples (x, y, z)
    P = list(itertools.product(range(10), repeat=3))
    # All possible questions (a, b, c)
    Q = list(itertools.product(range(10), repeat=3))

    # Try a few questions to see how they partition P
    for q in Q[:10]:
        responses = [f(q, p) for p in P]
        counts = {}
        for r in responses:
            counts[r] = counts.get(r, 0) + 1
        print(f"Question {q}: Max group size = {max(counts.values())}, Num groups = {len(counts)}")

solve()

