    Q = list(itertools.product(range(10), repeat=3))

    # Greedy search for q1, q2, q3
    chosen_qs = []
    for k in range(3):
        best_q = None
        min_max_size = 1000

        # To speed up, we can sample Q
        sample_Q = Q # Use all if possible

        for q in sample_Q:
            # Current partition signatures
            signatures = []
            for p in P:
                sig = tuple(f(cq, p) for cq in chosen_qs) + (f(q, p),)
                signatures.append(sig)

            counts = {}
            for sig in signatures:
