import itertools

def f(q, p):
    a, b, c = q
    x, y, z = p
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

def solve():
    P = list(itertools.product(range(10), repeat=3))
    Q = list(itertools.product(range(10), repeat=3))

    q1 = (0, 0, 0)
    S1_dict = {}
    for p in P:
        r = f(q1, p)
        if r not in S1_dict: S1_dict[r] = []
        S1_dict[r].append(p)

    max_r = max(S1_dict, key=lambda r: len(S1_dict[r]))
    S1 = S1_dict[max_r]

    # Greedy approach to find q2, q3 for S1
    chosen_qs = []
    min_max_size = len(S1)
    for k in range(2):
        best_q = None
        current_min_max = len(S1)
        for q in Q:
            signatures = []
            for p in S1:
                sig = tuple(f(cq, p) for cq in chosen_qs) + (f(q, p),)
                signatures.append(sig)

            counts = {}
            for sig in signatures:
                counts[sig] = counts.get(sig, 0) + 1

            max_size = max(counts.values())
            if max_size < current_min_max:
                current_min_max = max_size
                best_q = q
            if current_min_max == 1:
                break
        chosen_qs.append(best_q)
        min_max_size = current_min_max
        print(f"Question {k+2}: {best_q}, Min-max size: {min_max_size}")
        if min_max_size == 1:
            break

    if min_max_size == 1:
        print("Found 2 questions to distinguish S1!")
    else:
        print(f"Could not distinguish S1, min-max size is {min_max_size}")

solve()

